/* ===== original script 67 id=v227-profile-revamp-script ===== */

(()=>{
 function ps(){state.profileV227=state.profileV227||{name:'',avatarData:'',avatarUpdatedAt:0};return state.profileV227}
 function cleanName(v){return String(v||'').replace(/[^a-zA-Z0-9 _.'-]/g,'').replace(/\s+/g,' ').trim().slice(0,24)}
 function initials(v){const a=cleanName(v).split(/\s+/).filter(Boolean);return (a.length>1?(a[0][0]+a[a.length-1][0]):(a[0]||'C').slice(0,2)).toUpperCase()}
 function collectionValue(){try{const slabs=state.gradingV44?.graded||[];return Object.values(state.binder||{}).reduce((n,c)=>n+sellPrice(c)*Number(c.qty||0),0)+Object.values(state.bulkV64||{}).reduce((n,c)=>n+sellPrice(c)*Number(c.qty||0),0)+slabs.reduce((n,j)=>n+gradedValueV56(j),0)}catch(_){return 0}}
 function ranked(){const r=state.rankedV221||{};let name='Rookie';try{name=window.tcgRankedV221?.currentRank?.(Number(r.rp||0))?.name||name}catch(_){}return {rp:Number(r.rp||0),wins:Number(r.wins||0),losses:Number(r.losses||0),ties:Number(r.ties||0),streak:Number(r.streak||0),name}}
 async function signedIn(){try{const c=window.tcgMultiplayerV218?.client;if(!c)return null;const {data}=await c.auth.getUser();return data?.user||null}catch(_){return null}}
 async function cloudName(name){try{const c=window.tcgMultiplayerV218?.client,u=await signedIn();if(!c||!u)return false;let {error}=await c.rpc('mp_ensure_profile',{p_display_name:name});if(error)throw error;return true}catch(e){console.warn('profile name sync',e);return false}}
 function renderIdentity(){const s=ps(),r=ranked(),name=cleanName(s.name)||'Collector';const h=document.getElementById('profileDisplayNameV227'),inp=document.getElementById('profileNameInputV227'),fall=document.getElementById('profileAvatarFallbackV227'),img=document.getElementById('profileAvatarImgV227'),rp=document.getElementById('profileRpV227'),rn=document.getElementById('profileRankNameV227'),rec=document.getElementById('profileBattleRecordV227'),str=document.getElementById('profileBattleStreakV227'),cv=document.getElementById('profileCollectionValueV227');if(h)h.textContent=name;if(inp&&document.activeElement!==inp)inp.value=name;if(fall)fall.textContent=initials(name);if(img){if(s.avatarData){img.src=s.avatarData;img.hidden=false;if(fall)fall.style.opacity='0'}else{img.removeAttribute('src');img.hidden=true;if(fall)fall.style.opacity='1'}}if(rp)rp.textContent=Math.round(r.rp);if(rn)rn.textContent=r.name;if(rec)rec.textContent=`${r.wins}W · ${r.losses}L${r.ties?` · ${r.ties}T`:''}`;if(str)str.textContent=r.streak>1?`${r.streak} win streak`:'No active streak';if(cv)cv.textContent='$'+collectionValue().toFixed(2);signedIn().then(u=>{const pill=document.getElementById('profileOnlinePillV227');if(pill){pill.textContent=u?'CLOUD SYNC':'LOCAL';pill.classList.toggle('online',!!u)}})}
 async function saveName(){const inp=document.getElementById('profileNameInputV227');let name=cleanName(inp?.value);if(!name)return typeof toast==='function'&&toast('Enter a collector name.');ps().name=name;try{save()}catch(_){}renderIdentity();const mp=document.getElementById('mpNameV218');if(mp)mp.value=name;const ok=await cloudName(name);try{window.tcgCloudV192?.pushSilent?.()}catch(_){}if(typeof toast==='function')toast(ok?`✓ Collector name changed to ${name}`:`✓ Name changed to ${name}`)}
 function compressAvatar(file){return new Promise((resolve,reject)=>{if(!file||!String(file.type||'').startsWith('image/'))return reject(new Error('Choose an image file.'));if(file.size>15*1024*1024)return reject(new Error('Photo is too large.'));const reader=new FileReader();reader.onerror=()=>reject(new Error('Could not read photo.'));reader.onload=()=>{const im=new Image();im.onerror=()=>reject(new Error('Could not open photo.'));im.onload=()=>{try{const size=320,c=document.createElement('canvas');c.width=c.height=size;const ctx=c.getContext('2d',{alpha:false}),scale=Math.max(size/im.width,size/im.height),w=im.width*scale,h=im.height*scale,x=(size-w)/2,y=(size-h)/2;ctx.fillStyle='#ffffff';ctx.fillRect(0,0,size,size);ctx.drawImage(im,x,y,w,h);resolve(c.toDataURL('image/jpeg',.82))}catch(e){reject(e)}};im.src=reader.result};reader.readAsDataURL(file)})}
 async function chooseAvatar(file){try{const data=await compressAvatar(file);const s=ps();s.avatarData=data;s.avatarUpdatedAt=Date.now();save();renderIdentity();try{window.tcgCloudV192?.pushSilent?.()}catch(_){}if(typeof toast==='function')toast('✓ Profile picture updated')}catch(e){if(typeof toast==='function')toast(e?.message||'Could not update photo.')}}
 async function pullCloudName(){try{const s=ps();if(cleanName(s.name)&&cleanName(s.name)!=='Collector')return;const c=window.tcgMultiplayerV218?.client,u=await signedIn();if(!c||!u)return;const {data,error}=await c.from('mp_profiles').select('display_name').eq('user_id',u.id).maybeSingle();if(!error&&cleanName(data?.display_name)){s.name=cleanName(data.display_name);save();renderIdentity()}}catch(_){}}
 const old=window.renderProfile;if(typeof old==='function'&&!old.__v227){window.renderProfile=function(){const out=old.apply(this,arguments);try{renderIdentity()}catch(e){console.warn(e)}return out};window.renderProfile.__v227=true}
 document.addEventListener('click',e=>{if(e.target.closest('#profileAvatarBtnV227,#profileAvatarChooseV227')){document.getElementById('profileAvatarInputV227')?.click();return}if(e.target.closest('#profileAvatarResetV227')){const s=ps();s.avatarData='';s.avatarUpdatedAt=Date.now();save();renderIdentity();try{window.tcgCloudV192?.pushSilent?.()}catch(_){};if(typeof toast==='function')toast('Profile picture reset');return}if(e.target.closest('#profileSaveNameV227')){saveName();return}})
 document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target?.id==='profileNameInputV227'){e.preventDefault();saveName()}})
 document.getElementById('profileAvatarInputV227')?.addEventListener('change',e=>{const f=e.target.files?.[0];if(f)chooseAvatar(f);e.target.value=''})
 setTimeout(()=>{try{renderIdentity();pullCloudName()}catch(_){}},700)
 window.tcgProfileV227={renderIdentity,saveName,chooseAvatar};
 const row=[...document.querySelectorAll('.settingsDataLineV158')].find(x=>x.querySelector('span')?.textContent.trim()==='Game Version');if(row?.querySelector('b'))row.querySelector('b').textContent='V227 PROFILE IDENTITY REVAMP';
})();

